from pathlib import Path
import base64,gzip,hashlib,json,subprocess
root=Path('/tmp/ohm-target-size-prototypes')
evidence=root/'shipping-sparse-metadata'

def load(path):
    return json.loads(path.read_text())
def sha(path):
    with path.open('rb') as stream:
        return hashlib.file_digest(stream,'sha256').hexdigest()
def file_evidence(path):
    return {'sha256':sha(path),'bytes':path.stat().st_size}

subprocess.run(['python3',str(root/'sparse_metadata.py'),'report','--candidate','shipping-sparse','--experiment','shipping-sparse-metadata'],check=True,stdout=subprocess.DEVNULL)
for phase in ['native','instructions']:
    assert load(root/'shipping-sparse-measurement-receipts'/(phase+'.json'))['returncode']==0
summary=load(evidence/'summary.json')
summary['manifest']='provenance.json'
manifest=load(evidence/'manifest.json')
manifest['raw_manifest_sha256']=sha(evidence/'manifest.json')
manifest['measurement_harness_sha256']=sha(root/'sparse_metadata.py')
manifest['harness_commits']={'preparation_and_initial_storage':'de2e243894f9003fe6a898fd1c242b2bb44811a0','measurement_and_final_accounting':'4e23d8dabdd5e6cfd2df667ce9dc36b10cfaeea7'}
manifest['physical_root']=str(root.resolve())
manifest['profiles_note']='Full profiles remain on the persistent task VM; exported evidence includes their hashes, byte sizes, Ir counts, and raw compiler/Valgrind logs.'
for arm,entry in manifest['arms'].items():
    assert sha(Path(entry['sysroot'])/'bin/rustc')==entry['rustc_sha256']
    assert all(sha(Path(path))==expected for path,expected in entry['driver_sha256'].items())
    for preparation in entry['preparation']:
        inventory=preparation.pop('metadata')
        assert all(sha(Path(item['path']))==item['sha256'] for item in inventory)
        preparation['dependency_metadata_unchanged']=True
        preparation['metadata_file_count']=len(inventory)
        preparation['metadata_logical_bytes']=sum(item['bytes'] for item in inventory)
        preparation['log_evidence']=file_evidence(Path(preparation['log']))
manifest['measurement_environments']={}
records={}
for phase in ['native','instructions']:
    path=evidence/phase/'samples.json'
    environment=load(evidence/phase/'environment.json')
    cpuinfo=environment.pop('cpuinfo')
    environment['cpuinfo_first_processor']=cpuinfo.split('\n\n')[0]
    environment['cpuinfo_sha256']=hashlib.sha256(cpuinfo.encode()).hexdigest()
    environment['raw_samples_sha256']=sha(path)
    manifest['measurement_environments'][phase]=environment
    rows=load(path)
    records[phase]=[]
    for raw in rows:
        row={key:value for key,value in raw.items() if key not in ['command','cwd','environment','log','cachegrind']}
        row['command_reference']=raw['arm']+'.'+raw['case']
        row['log_evidence']=file_evidence(Path(raw['log']))
        if 'cachegrind' in raw:
            row['cachegrind_evidence']=file_evidence(Path(raw['cachegrind']))
        for file in row['metadata']:
            file['path']=Path(file['path']).name
        records[phase].append(row)
validation={}
for name in ['baseline-build','shipping-sparse-build','baseline-runtime','shipping-sparse-runtime','sparse-units','sparse-run-make']:
    path=root/'shipping-validation'/(name+'.json')
    validation[name]=load(path)
    log=path.with_suffix('.log')
    if log.exists():
        validation[name]['log_evidence']=file_evidence(log)
        validation[name]['test_result_lines']=[line for line in log.read_text().splitlines() if 'test result:' in line]
validation['storage_stabilization']=load(root/'shipping-sparse-input-preparation/stabilized-storage.json')
raw_files={}
for folder in [evidence,root/'shipping-validation',root/'shipping-sparse-input-preparation',root/'shipping-sparse-measurement-receipts']:
    for path in sorted(folder.rglob('*')):
        if path.is_file() and path.suffix in ['.json','.log']:
            raw_files[str(path.relative_to(root))]=path.read_text()
for name in ['baseline','shipping-sparse']:
    path=root/'logs'/(name+'-status.json')
    raw_files[str(path.relative_to(root))]=path.read_text()
raw_data=gzip.compress(json.dumps(raw_files).encode(),mtime=0)
manifest['raw_evidence_sha256']=hashlib.sha256(raw_data).hexdigest()
manifest['raw_evidence_file_count']=len(raw_files)
compact={'results.json':summary,'provenance.json':manifest,'samples.json':records,'validation.json':validation,'profile-diagnostic.json':load(evidence/'diagnostics/parser-profile-diff-slash/receipt.json')}
payload={'compact':compact,'raw_evidence':base64.b64encode(raw_data).decode()}
encoded=json.dumps(payload).encode()
packed=gzip.compress(encoded,mtime=0)
output=root/'shipping-sparse-export.json.gz'
output.write_bytes(packed)
print(json.dumps({'sha256':hashlib.sha256(encoded).hexdigest(),'archive_sha256':sha(output),'archive_bytes':len(packed),'path':str(output),'results':summary}))

